mapper.update:
UPDATE users
SET password = #{password}
WHERE id = #{userId}

UPDATE users
SET must_change_password = #{value}
WHERE id = #{userId}

UPDATE users
SET otp_secret = #{otpSecret},
    otp_enabled = #{otpEnabled}
WHERE id = #{userId}

UPDATE users
SET profile_image_filename = #{profileImageFilename}
WHERE id = #{userId}

UPDATE users
SET signature_filename = #{signatureFilename}
WHERE id = #{userId}

UPDATE users
SET active = FALSE
WHERE id = #{userId}

mapper.delete:
DELETE FROM user_roles
WHERE user_id = #{userId}
  AND role_code = #{roleCode}
